/// Tagged offline region definition.
///
/// See `mln_offline_region_definition` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html).
public struct OfflineRegionDefinition: Equatable, Hashable, Sendable {
  public var data: OfflineRegionDefinitionData
  public static var `default`: Self {
    Self()
  }

  public static func tilePyramid(_ value: OfflineTilePyramidRegionDefinition)
    -> Self
  {
    Self(data: .tilePyramid(value))
  }

  public static func geometry(_ value: OfflineGeometryRegionDefinition)
    -> Self
  {
    Self(data: .geometry(value))
  }

  public init(data: OfflineRegionDefinitionData = .default) {
    self.data = data
  }

  init(
    raw: mln_offline_region_definition,
    recordBytes: UnsafeRawBufferPointer? = nil
  ) throws {
    data = try { () throws -> OfflineRegionDefinitionData in
      switch raw
        .type
      {
      case MLN_OFFLINE_REGION_DEFINITION_TILE_PYRAMID
        .rawValue: return try .tilePyramid(
          OfflineTilePyramidRegionDefinition(raw: raw
            .data.tile_pyramid)
        ) case MLN_OFFLINE_REGION_DEFINITION_GEOMETRY
        .rawValue: return try .geometry(OfflineGeometryRegionDefinition(raw: raw
            .data.geometry)) default: return .unknown(
          raw.type,
          recordBytes
            .map {
              Data($0
                .dropFirst(MemoryLayout<mln_offline_region_definition>
                  .offset(of: \.data)!))
            } ?? withUnsafeBytes(of: raw.data) { Data($0) }
        )
      }
    }()
  }

  func nativeValue(arena: NativeInputArena) throws
    -> mln_offline_region_definition
  {
    var raw = mln_offline_region_definition()
    raw.size = UInt32(MemoryLayout<mln_offline_region_definition>.size)
    switch data {
    case let .tilePyramid(item): raw
      .type = MLN_OFFLINE_REGION_DEFINITION_TILE_PYRAMID.rawValue; raw.data
      .tile_pyramid = try item.nativeValue(arena: arena)
    case let .geometry(item): raw.type = MLN_OFFLINE_REGION_DEFINITION_GEOMETRY
      .rawValue; raw.data.geometry = try item.nativeValue(arena: arena)
    case .unknown: throw NativeStringError(
        "unknown union variant cannot be submitted"
      )
    }
    return raw
  }
}

